const base = 'https://kalpalabs.app.n8n.cloud';
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fmt = (d) => d ? new Date(d).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' }) : '';
const hasData = (i) => i.json && Object.keys(i.json).length > 0;

const workflows = $('Get Workflows').all().filter(hasData).map(i => i.json);
const executions = $input.all().filter(hasData).map(i => i.json);
const wfName = {};
workflows.forEach(w => { wfName[w.id] = w.name; });

workflows.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));
executions.sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt));

const dayAgo = Date.now() - 24 * 3600 * 1000;
const changed24h = workflows.filter(w => new Date(w.updatedAt).getTime() > dayAgo).length;
const published = workflows.filter(w => w.active).length;
const errors = executions.filter(e => e.status === 'error' || e.status === 'crashed').length;

const badge = (txt, cls) => '<span class="badge ' + cls + '">' + esc(txt) + '</span>';

let wfRows = '';
workflows.forEach(w => {
  const isNew = new Date(w.createdAt).getTime() > dayAgo;
  wfRows += '<tr><td><a href="' + base + '/workflow/' + esc(w.id) + '" target="_blank">' + esc(w.name) + '</a>' + (isNew ? ' ' + badge('new', 'new') : '') + '</td>'
    + '<td>' + (w.active ? badge('published', 'ok') : badge('draft', 'muted')) + '</td>'
    + '<td>' + (Array.isArray(w.nodes) ? w.nodes.length : '') + '</td>'
    + '<td>' + fmt(w.updatedAt) + '</td>'
    + '<td>' + fmt(w.createdAt) + '</td></tr>';
});

let exRows = '';
executions.forEach(e => {
  const cls = e.status === 'success' ? 'ok' : (e.status === 'error' || e.status === 'crashed') ? 'err' : 'muted';
  const dur = e.startedAt && e.stoppedAt ? ((new Date(e.stoppedAt) - new Date(e.startedAt)) / 1000).toFixed(1) + 's' : '';
  exRows += '<tr><td><a href="' + base + '/workflow/' + esc(e.workflowId) + '/executions/' + esc(e.id) + '" target="_blank">#' + esc(e.id) + '</a></td>'
    + '<td>' + esc(wfName[e.workflowId] || e.workflowId) + '</td>'
    + '<td>' + badge(e.status || (e.finished ? 'success' : 'unknown'), cls) + '</td>'
    + '<td>' + esc(e.mode) + '</td>'
    + '<td>' + fmt(e.startedAt) + '</td>'
    + '<td>' + dur + '</td></tr>';
});

const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<meta http-equiv="refresh" content="60"><title>n8n Activity Dashboard</title><style>'
  + 'body{font-family:system-ui,-apple-system,sans-serif;background:#0f1117;color:#e6e6e6;margin:0;padding:24px}'
  + 'h1{margin:0 0 4px;font-size:22px}h2{font-size:16px;margin:28px 0 10px}.sub{color:#8a8f98;font-size:13px}'
  + '.cards{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}.card{background:#1a1d27;border:1px solid #2a2e3a;border-radius:10px;padding:14px 18px;min-width:150px}'
  + '.card .n{font-size:26px;font-weight:600}.card .l{color:#8a8f98;font-size:12px}'
  + 'input{background:#1a1d27;border:1px solid #2a2e3a;color:#e6e6e6;border-radius:8px;padding:8px 10px;width:280px}'
  + 'table{width:100%;border-collapse:collapse;background:#1a1d27;border-radius:10px;overflow:hidden;font-size:13px}'
  + 'th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #2a2e3a}th{color:#8a8f98;font-weight:500;background:#151821}'
  + 'a{color:#ff8a65;text-decoration:none}a:hover{text-decoration:underline}'
  + '.badge{padding:2px 8px;border-radius:999px;font-size:11px}.ok{background:#1e4620;color:#7ee787}.err{background:#4a1d1d;color:#ff7b72}'
  + '.muted{background:#2a2e3a;color:#aab}.new{background:#3b2a5c;color:#d2a8ff}'
  + '</style></head><body>'
  + '<h1>n8n Activity Dashboard</h1><div class="sub">Workflows built or edited (including by Claude via MCP) and recent runs. Auto-refreshes every 60s. Generated ' + fmt(new Date()) + '</div>'
  + '<div class="cards">'
  + '<div class="card"><div class="n">' + workflows.length + '</div><div class="l">Workflows</div></div>'
  + '<div class="card"><div class="n">' + changed24h + '</div><div class="l">Changed in last 24h</div></div>'
  + '<div class="card"><div class="n">' + published + '</div><div class="l">Published</div></div>'
  + '<div class="card"><div class="n">' + executions.length + '</div><div class="l">Recent runs</div></div>'
  + '<div class="card"><div class="n">' + errors + '</div><div class="l">Failed runs</div></div>'
  + '</div>'
  + '<h2>Workflows (most recently changed first)</h2><input id="q" placeholder="Filter workflows..." oninput="f()">'
  + '<table id="wf" style="margin-top:10px"><thead><tr><th>Name</th><th>Status</th><th>Nodes</th><th>Last updated</th><th>Created</th></tr></thead><tbody>' + (wfRows || '<tr><td colspan="5">No workflows</td></tr>') + '</tbody></table>'
  + '<h2>Recent executions</h2>'
  + '<table><thead><tr><th>Run</th><th>Workflow</th><th>Status</th><th>Mode</th><th>Started</th><th>Duration</th></tr></thead><tbody>' + (exRows || '<tr><td colspan="6">No executions</td></tr>') + '</tbody></table>'
  + '<script>function f(){var q=document.getElementById("q").value.toLowerCase();document.querySelectorAll("#wf tbody tr").forEach(function(r){r.style.display=r.textContent.toLowerCase().indexOf(q)>-1?"":"none";});}</script>'
  + '</body></html>';

return [{ json: { html } }];
